CREATE OR REPLACE FUNCTION public.admin_register_business(_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid; v uuid; BEGIN IF NOT is_platform_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT id INTO p FROM subscription_plans WHERE slug=_payload->>'plan_slug' AND is_active IS NOT FALSE; IF p IS NULL OR trim(coalesce(_payload->>'business_name',''))='' THEN RAISE EXCEPTION 'Business name and plan are required'; END IF; INSERT INTO pharmacies(name,business_type,owner_name,email,phone,city,address,registration_number,tax_number,plan_id,billing_choice,status) VALUES(_payload->>'business_name','pharmacy',_payload->>'owner_name',_payload->>'email',_payload->>'phone',_payload->>'city',_payload->>'address',_payload->>'registration_number',_payload->>'tax_number',p,'trial','pending') RETURNING id INTO v; INSERT INTO audit_logs(pharmacy_id,user_id,action,entity,entity_id) VALUES(v,auth.uid(),'registration_submitted','pharmacy',v::text); RETURN v; END $$;
REVOKE ALL ON FUNCTION public.admin_register_business(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_register_business(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.update_staff_details(_pharmacy uuid,_membership uuid,_row jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[]:='{}'; b uuid; code text; BEGIN IF NOT can_write_pharmacy(_pharmacy,ARRAY[]::user_role[]) THEN RAISE EXCEPTION 'Owner or admin required'; END IF; FOR code IN SELECT trim(x) FROM unnest(string_to_array(nullif(_row->>'branch_codes',''),';')) x LOOP SELECT id INTO b FROM branches WHERE pharmacy_id=_pharmacy AND lower(branches.code)=lower(code); IF b IS NULL THEN RAISE EXCEPTION 'Unknown branch code'; END IF; ids:=array_append(ids,b); END LOOP; UPDATE pharmacy_memberships SET phone=_row->>'phone',staff_id=_row->>'staff_id',job_title=_row->>'job_title',role=(_row->>'role')::user_role,employment_status=_row->>'employment_status',branch_ids=ids,branch_id=CASE WHEN cardinality(ids)=1 THEN ids[1] ELSE NULL END WHERE id=_membership AND pharmacy_id=_pharmacy; IF NOT FOUND THEN RAISE EXCEPTION 'Staff not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.update_staff_details(uuid,uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_staff_details(uuid,uuid,jsonb) TO authenticated;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.save_business_entry(uuid,text,jsonb,uuid)'::regprocedure) INTO definition; definition:=replace(definition,'INSERT INTO inventory_batches(pharmacy_id,product_id,branch_id,batch_number,quantity,cost_per_unit,manufacturing_date,expiry_date,received_date)', 'IF coalesce((_row->>''quantity'')::int,0)<=0 THEN RAISE EXCEPTION ''Opening stock quantity must be greater than zero''; END IF;'||chr(10)||'  INSERT INTO inventory_batches(pharmacy_id,product_id,branch_id,batch_number,quantity,cost_per_unit,manufacturing_date,expiry_date,received_date)'); EXECUTE definition; END $$;